//! 🎯️ Aggregate targets delegate to each actual authored leaf source and preserve its original identity fragments.
use super::*;
pub(super)fn expand(input:&DeriveInput)->syn::Result<Tokens>{let syn::Data::Enum(data)=&input.data else{return Err(error("native aggregate targets require the actual mutation enum"))};if data.variants.is_empty(){return Err(error("native aggregate targets require authored leaf variants"))}let name=&input.ident;let mut variants=Vec::new();for v in &data.variants{if !matches!(&v.fields,syn::Fields::Unnamed(f)if f.unnamed.len()==1){return Err(error("native target variants must retain their actual single leaf payload"))}variants.push(&v.ident);}let(implementation,types,where_clause)=input.generics.split_for_impl();Ok(quote!{impl #implementation ::semio_s_artifact_energy_model_native_mutations::target::ArtifactOperationTargets for #name #types #where_clause{fn len(&self)->usize{match self{#(Self::#variants(p)=>::semio_s_artifact_energy_model_native_mutations::target::ArtifactOperationTargets::len(p)),*}}fn segment_len(&self,index:usize)->Result<usize,::semio_framework_value::ValueError>{match self{#(Self::#variants(p)=>::semio_s_artifact_energy_model_native_mutations::target::ArtifactOperationTargets::segment_len(p,index)),*}}fn read_segment(&self,index:usize,offset:usize,output:&mut[u8])->Result<usize,::semio_framework_value::ValueError>{match self{#(Self::#variants(p)=>::semio_s_artifact_energy_model_native_mutations::target::ArtifactOperationTargets::read_segment(p,index,offset,output)),*}}}})}
